CREATE TABLE IF NOT EXISTS hero_slide(id INT AUTO_INCREMENT PRIMARY KEY,gambar VARCHAR(100),urut INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
